<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  sid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Session ID base64url(uint64 ≠ 0); REQUIRED for clients</span></span>
